const textoRespuesta = $input.first().json.content.parts[0].text;
const textoLimpio = textoRespuesta.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
let datos = {};
try {
  datos = JSON.parse(textoLimpio);
} catch (error) {
  datos = {
    experiencia_anios: 0,
    habilidades: [],
    nivel_educativo: 'No especificado',
    compatibilidad: 0,
    resumen_perfil: 'Sin resumen disponible',
    preguntas_entrevista: [],
    observaciones: 'Error al procesar JSON'
  };
}

return [{
  json: {
    experiencia_anios: Number(datos.experiencia_anios) || 0,
    habilidades: Array.isArray(datos.habilidades) ? datos.habilidades.join(', ') : (datos.habilidades || ''),
    nivel_educativo: datos.nivel_educativo || 'No especificado',
    compatibilidad: Number(datos.compatibilidad) || 0,
    resumen_perfil: datos.resumen_perfil || '',
    preguntas_entrevista: Array.isArray(datos.preguntas_entrevista) ? datos.preguntas_entrevista.join(' | ') : (datos.preguntas_entrevista || ''),
    observaciones: datos.observaciones || ''
  }
}];

// Recupera el binario original del Webhook, que se perdió al pasar por Google Sheets
const binaryOriginal = $('Postularse').item.binary;

return [{
  json: $input.item.json,
  binary: binaryOriginal
}];

