return $input.all().map(item => {
  const row = item.json;

  // Extrae y limpia el Score_Compatibilidad de Google Sheets
  const rawScore = row.Score_Compatibilidad || row.Score || row.score || 0;
  const scoreNumero = typeof rawScore === 'string'
    ? parseFloat(rawScore.replace('%', '').trim()) || 0
    : Number(rawScore || 0);

  return {
    json: {
      id: row.ID_Candidato || row.ID || row.id || 'N/A',
      nombre: row.Nombre || row.nombre || 'Sin nombre',
      vacante: row.Vacante || row.vacante || 'No especificada',
      experiencia: row.Experiencia || row.experiencia || '0 años',
      score: scoreNumero,
      estado: row.Estado || row.estado || 'Pendiente',
      // ✅ Clave para leer la columna de Google Sheets:
      revision: row.Revision_RRHH || row['Revisión RRHH'] || row['Revision RRHH'] || row.Revision || 'Sin revisar'
    }
  };
});

